#include <vector>
#include <algorithm>

class Solution {
public:
    int maxProfitWithCooldown(std::vector<int>& prices, int k) {
        if (prices.empty()) return 0;
        int n = prices.size();
        int hold = -prices[0];
        std::vector<int> sold(k + 1, 0);
        int rest = 0;

        for (size_t i = 1; i < prices.size(); ++i) {
            int p = prices[i];
            int prev_hold = hold;
            int can_buy = std::max(rest, sold.back());
            hold = std::max(hold, can_buy - p);
            rest = std::max(rest, sold.back());

            int curr_sold = prev_hold + p;
            for (int j = k; j >= 1; --j) {
                sold[j] = sold[j - 1];
            }
            sold[0] = curr_sold;
        }

        int max_s = *std::max_element(sold.begin(), sold.end());
        return std::max(rest, max_s);
    }
};

class Solution {
    public int maxProfitWithCooldown(int[] prices, int k) {
        if (prices.length == 0) return 0;
        int hold = -prices[0];
        int[] sold = new int[k + 1];
        int rest = 0;

        for (int i = 1; i < prices.length; i++) {
            int p = prices[i];
            int prevHold = hold;
            int canBuy = Math.max(rest, sold[k]);
            hold = Math.max(hold, canBuy - p);
            rest = Math.max(rest, sold[k]);

            int currSold = prevHold + p;
            for (int j = k; j >= 1; j--) {
                sold[j] = sold[j - 1];
            }
            sold[0] = currSold;
        }

        int maxS = 0;
        for (int s : sold) maxS = Math.max(maxS, s);
        return Math.max(rest, maxS);
    }
}

